/**
 *  dispatch_command의 GameResponse와 같은 취지: 프론트가 "이벤트 배열 받아서 처리"
 *  하나로 엔진 커맨드/AI 대화 두 경로를 똑같이 다루게 한다.
 */
export type NpcReply = NpcReply_Serialize | NpcReply_Deserialize;

/**
 *  dispatch_command의 GameResponse와 같은 취지: 프론트가 "이벤트 배열 받아서 처리"
 *  하나로 엔진 커맨드/AI 대화 두 경로를 똑같이 다루게 한다.
 */
export type NpcReply_Deserialize = {
	/**  <choice> 태그를 벗겨낸 텍스트 */
	text: string,
	/**  보통 [] 또는 [ChoicePresented]. ChoicePresented는 시스템이 아니라 여기서만 만들어진다. */
	events: GameEvent_Deserialize[],
	/**  줄 단위로 나눈 응답 + 줄마다 실행할 연출 (표정, 효과음, BGM, CG, 화면 효과). text는 같은 내용의 평문(`이름: 대사`)이다. */
	lines: StageLine_Deserialize[],
	/**  AI가 바꾼 변수/그로 인한 이벤트가 반영된 뒤의 상태. 프론트가 그대로 맞춘다. */
	state: RenderState_Deserialize,
};

/**
 *  dispatch_command의 GameResponse와 같은 취지: 프론트가 "이벤트 배열 받아서 처리"
 *  하나로 엔진 커맨드/AI 대화 두 경로를 똑같이 다루게 한다.
 */
export type NpcReply_Serialize = {
	/**  <choice> 태그를 벗겨낸 텍스트 */
	text: string,
	/**  보통 [] 또는 [ChoicePresented]. ChoicePresented는 시스템이 아니라 여기서만 만들어진다. */
	events: GameEvent_Serialize[],
	/**  줄 단위로 나눈 응답 + 줄마다 실행할 연출 (표정, 효과음, BGM, CG, 화면 효과). text는 같은 내용의 평문(`이름: 대사`)이다. */
	lines: StageLine_Serialize[],
	/**  AI가 바꾼 변수/그로 인한 이벤트가 반영된 뒤의 상태. 프론트가 그대로 맞춘다. */
	state: RenderState_Serialize,
};

/**  open_game의 응답: 프로젝트 정보 + 화면에 그릴 정적 데이터(get_game_view와 같은 값) + 그 내용 해시 + 진단 결과. */
export type OpenGameResponse = OpenGameResponse_Serialize | OpenGameResponse_Deserialize;

/**  open_game의 응답: 프로젝트 정보 + 화면에 그릴 정적 데이터(get_game_view와 같은 값) + 그 내용 해시 + 진단 결과. */
export type OpenGameResponse_Deserialize = {
	project: GameProject_Deserialize,
	view: Value,
	/**  view의 내용 해시. 프론트가 캐시해둔 정적 데이터가 아직 유효한지 비교한다 (같으면 그대로 쓰면 된다). */
	contentHash: string,
	/**
	 *  에셋을 불러오는 기준 URL (끝에 `/`). view와 이벤트/무대 상태의 에셋 path는 게임 폴더 기준 상대경로이고,
	 *  프론트는 `assetBaseUrl + path`로 이미지/오디오를 불러온다 (경로의 각 조각은 URL 인코딩).
	 */
	assetBaseUrl: string,
	/**  데이터 진단 결과(같은 진단은 한 번만). Error가 하나라도 있으면 start_new_game이 시작을 막는다. */
	diagnostics: Issue[],
};

/**  open_game의 응답: 프로젝트 정보 + 화면에 그릴 정적 데이터(get_game_view와 같은 값) + 그 내용 해시 + 진단 결과. */
